fig('R01',[FANP(60,100)+WINDA(84,88,3,40)+WINDA(84,88,0), PITOTP(300,100)+WINDA(250,90,3,30)+UTUBE(430,70,40,60), UTUBE(580,76,40,60)+LAB(640,100,'Δh')],[('선풍기 → 풍속 v',"#fbbf24"),('동압 ½ρv² = Δp','#7dd3fc'),('Δh = Δp/ρg','#34d399')],[(60,100),(300,100),(600,106)])
